```php
<?php

declare(strict_types=1);

/**
 * Represents a single line item in the shopping cart.
 */
final class CartItem
{
    public function __construct(
        public readonly string $id,
        public readonly string $name,
        public readonly float $price,
        private int $quantity = 1
    ) {
        if ($price < 0) {
            throw new InvalidArgumentException('Price cannot be negative.');
        }
        if ($quantity < 1) {
            throw new InvalidArgumentException('Quantity must be at least 1.');
        }
    }

    public function getQuantity(): int
    {
        return $this->quantity;
    }

    public function increaseQuantity(int $amount): void
    {
        if ($amount < 1) {
            throw new InvalidArgumentException('Amount must be at least 1.');
        }
        $this->quantity += $amount;
    }

    public function decreaseQuantity(int $amount): void
    {
        if ($amount < 1) {
            throw new InvalidArgumentException('Amount must be at least 1.');
        }
        $this->quantity = max(0, $this->quantity - $amount);
    }

    public function getSubtotal(): float
    {
        return $this->price * $this->quantity;
    }
}

/**
 * A simple shopping cart that supports adding, removing, and totaling items.
 */
class ShoppingCart
{
    /** @var array<string, CartItem> */
    private array $items = [];

    /**
     * Add an item to the cart. If the item already exists, its quantity is increased.
     */
    public function addItem(string $id, string $name, float $price, int $quantity = 1): void
    {
        if (isset($this->items[$id])) {
            $this->items[$id]->increaseQuantity($quantity);
            return;
        }

        $this->items[$id] = new CartItem($id, $name, $price, $quantity);
    }

    /**
     * Remove an item from the cart.
     *
     * @param string   $id       The item ID.
     * @param int|null $quantity Number of units to remove; null removes the item entirely.
     * @return bool True if the item was found and removed/reduced, false otherwise.
     */
    public function removeItem(string $id, ?int $quantity = null): bool
    {
        if (!isset($this->items[$id])) {
            return false;
        }

        if ($quantity === null) {
            unset($this->items[$id]);
            return true;
        }

        $this->items[$id]->decreaseQuantity($quantity);

        if ($this->items[$id]->getQuantity() === 0) {
            unset($this->items[$id]);
        }

        return true;
    }

    /**
     * Get the total cost of all items in the cart.
     */
    public function getTotal(): float
    {
        $total = 0.0;

        foreach ($this->items as $item) {
            $total += $item->getSubtotal();
        }

        return round($total, 2);
    }

    /**
     * @return array<string, CartItem>
     */
    public function getItems(): array
    {
        return $this->items;
    }

    public function getItemCount(): int
    {
        return array_sum(array_map(fn(CartItem $i) => $i->getQuantity(), $this->items));
    }

    public function isEmpty(): bool
    {
        return empty($this->items);
    }

    public function clear(): void
    {
        $this->items = [];
    }
}
