```php
<?php

declare(strict_types=1);

/**
 * Represents a single product line in the cart.
 */
final class CartItem
{
    public function __construct(
        public readonly string $id,
        public readonly string $name,
        public readonly int $priceInCents,
        public int $quantity = 1
    ) {
        if ($priceInCents < 0) {
            throw new InvalidArgumentException('Price cannot be negative.');
        }
        if ($quantity < 1) {
            throw new InvalidArgumentException('Quantity must be at least 1.');
        }
    }

    public function subtotal(): int
    {
        return $this->priceInCents * $this->quantity;
    }
}

/**
 * A simple shopping cart.
 *
 * Prices are stored as integers (cents) to avoid floating-point rounding errors.
 */
class ShoppingCart
{
    /** @var array<string, CartItem> */
    private array $items = [];

    /**
     * Add an item to the cart. If it already exists, its quantity is increased.
     */
    public function addItem(string $id, string $name, int $priceInCents, int $quantity = 1): void
    {
        if ($quantity < 1) {
            throw new InvalidArgumentException('Quantity must be at least 1.');
        }

        if (isset($this->items[$id])) {
            $this->items[$id]->quantity += $quantity;
            return;
        }

        $this->items[$id] = new CartItem($id, $name, $priceInCents, $quantity);
    }

    /**
     * Remove an item from the cart.
     *
     * If $quantity is null, the item is removed entirely.
     * Otherwise, the quantity is reduced; the item is removed if it reaches zero.
     *
     * @return bool True if the item was found, false otherwise.
     */
    public function removeItem(string $id, ?int $quantity = null): bool
    {
        if (!isset($this->items[$id])) {
            return false;
        }

        if ($quantity === null || $quantity >= $this->items[$id]->quantity) {
            unset($this->items[$id]);
            return true;
        }

        if ($quantity < 1) {
            throw new InvalidArgumentException('Quantity must be at least 1.');
        }

        $this->items[$id]->quantity -= $quantity;
        return true;
    }

    /**
     * Get the cart total in cents.
     */
    public function getTotal(): int
    {
        return array_reduce(
            $this->items,
            fn (int $sum, CartItem $item) => $sum + $item->subtotal(),
            0
        );
    }

    /**
     * Get the cart total formatted as a currency string.
     */
    public function getFormattedTotal(string $symbol = '$'): string
    {
        return $symbol . number_format($this->getTotal() / 100, 2);
    }

    /** @return CartItem[] */
    public function getItems(): array
    {
        return array_values($this->items);
    }

    public function isEmpty(): bool
    {
        return $this->items === [];
    }

    public function clear(): void
    {
        $this->items = [];
    }
}
