            return false;
        }

        if ($quantity === null) {
            unset($this->items[$id]);
            return true;
        }

        $this->items[$id]->decreaseQuantity($quantity);

        if ($this->items[$id]->getQuantity() === 0) {
            unset($this->items[$id]);
        }

        return true;
    }

