```php
<?php

/**
 * Convert a string into a URL-safe slug.
 *
 * Example: "Héllo Wörld! It's 2024 & Beyond" => "hello-world-its-2024-beyond"
 *
 * @param string $string    The input string (e.g., a title).
 * @param string $separator The word separator (default "-").
 * @return string           The slugified string.
 */
function slugify(string $string, string $separator = '-'): string
{
    // 1. Transliterate to ASCII (e.g., "é" -> "e", "ß" -> "ss").
    if (class_exists('Transliterator')) {
        // Best option: requires the intl extension.
        $transliterator = Transliterator::create('Any-Latin; Latin-ASCII; Lower()');
        if ($transliterator !== null) {
            $string = $transliterator->transliterate($string);
        }
    } elseif (function_exists('iconv')) {
        // Fallback: iconv transliteration (results vary by system locale).
        $converted = @iconv('UTF-8', 'ASCII//TRANSLIT//IGNORE', $string);
        if ($converted !== false) {
            $string = $converted;
        }
    }

    // 2. Lowercase (multibyte-safe in case transliteration wasn't available).
    $string = function_exists('mb_strtolower')
        ? mb_strtolower($string, 'UTF-8')
        : strtolower($string);

    // 3. Remove apostrophes so "it's" becomes "its" rather than "it-s".
    $string = str_replace(["'", '’', '`'], '', $string);

    // 4. Replace any run of non-alphanumeric characters with the separator.
    $quotedSeparator = preg_quote($separator, '/');
    $string = preg_replace('/[^a-z0-9]+/', $separator, $string);

    // 5. Collapse repeated separators and trim them from the ends.
    $string = preg_replace('/' . $quotedSeparator . '+/', $separator, $string);
    $string = trim($string, $separator);

    return $string;
}
```

