echo slugify("  Héllo Wörld! It's 2024 & Beyond "); // hello-world-its-2024-beyond
echo slugify("Crème Brûlée Recipe");                // creme-brulee-recipe
echo slugify("Straße in München");                  // strasse-in-munchen
echo slugify("PHP: The Right Way (2nd Ed.)");       // php-the-right-way-2nd-ed
echo slugify("---Multiple   Spaces---");            // multiple-spaces
