class ShoppingCart
{
    /** @var array<string, array{name: string, price: float, quantity: int}> */
    private array $items = [];

    /**
     * Add an item to the cart. If it already exists, increase its quantity.
     */
    public function addItem(string $id, string $name, float $price, int $quantity = 1): void
    {
        if ($price < 0) {
            throw new InvalidArgumentException('Price cannot be negative.');
        }
        if ($quantity < 1) {
            throw new InvalidArgumentException('Quantity must be at least 1.');
        }

        if (isset($this->items[$id])) {
            $this->items[$id]['quantity'] += $quantity;
        } else {
            $this->items[$id] = [
                'name'     => $name,
                'price'    => $price,
                'quantity' => $quantity,
            ];
        }
    }

    /**
     * Remove an item from the cart.
     * If $quantity is null, the item is removed entirely.
     * Otherwise, that many units are removed (item is deleted if quantity reaches 0).
     */
    public function removeItem(string $id, ?int $quantity = null): void
    {
        if (!isset($this->items[$id])) {
            throw new OutOfBoundsException("Item '$id' is not in the cart.");
        }

        if ($quantity === null) {
            unset($this->items[$id]);
            return;
        }

        if ($quantity < 1) {
            throw new InvalidArgumentException('Quantity must be at least 1.');
        }

        $this->items[$id]['quantity'] -= $quantity;

        if ($this->items[$id]['quantity'] <= 0) {
            unset($this->items[$id]);
        }
    }

    /**
     * Get the total price of all items in the cart.
     */
    public function getTotal(): float
    {
        $total = 0.0;
        foreach ($this->items as $item) {
            $total += $item['price'] * $item['quantity'];
        }
        return round($total, 2);
    }

    /**
     * Get all items in the cart.
     */
    public function getItems(): array
    {
        return $this->items;
    }
}

// Example usage
$cart = new ShoppingCart();
$cart->addItem('apple', 'Apple', 0.50, 6);
$cart->addItem('bread', 'Bread', 2.25);
$cart->addItem('apple', 'Apple', 0.50, 2); // apple quantity is now 8

echo $cart->getTotal() . PHP_EOL; // 6.25

$cart->removeItem('apple', 3);    // 5 apples left
echo $cart->getTotal() . PHP_EOL; // 4.75

$cart->removeItem('bread');       // remove bread entirely
echo $cart->getTotal() . PHP_EOL; // 2.5
```

**Notes:**
- Items are keyed by ID, so adding the same item twice merges quantities.
- `removeItem` removes the whole item by default, or a specific number of units if you pass a quantity.
- Invalid input (negative price, zero quantity, removing a nonexistent item) throws an exception.
- For real-world money handling, consider storing prices as integer cents to avoid floating-point rounding issues.

