<?php

declare(strict_types=1);

class ShoppingCart
{
    /** @var array<string, array{name: string, price: float, quantity: int}> */
    private array $items = [];

    /**
     * Add an item to the cart. If the item already exists, increase its quantity.
     */
    public function addItem(string $id, string $name, float $price, int $quantity = 1): void
    {
        if ($price < 0) {
            throw new InvalidArgumentException('Price cannot be negative.');
        }
        if ($quantity < 1) {
            throw new InvalidArgumentException('Quantity must be at least 1.');
        }

        if (isset($this->items[$id])) {
            $this->items[$id]['quantity'] += $quantity;
        } else {
            $this->items[$id] = [
                'name'     => $name,
                'price'    => $price,
                'quantity' => $quantity,
            ];
        }
    }

    /**
     * Remove an item from the cart.
     * If $quantity is null, the item is removed entirely.
     * Otherwise, the given quantity is subtracted (removing the item if it reaches 0).
     */
    public function removeItem(string $id, ?int $quantity = null): void
    {
        if (!isset($this->items[$id])) {
            throw new OutOfBoundsException("Item '$id' is not in the cart.");
        }

        if ($quantity === null || $quantity >= $this->items[$id]['quantity']) {
            unset($this->items[$id]);
            return;
        }

        if ($quantity < 1) {
            throw new InvalidArgumentException('Quantity must be at least 1.');
        }

        $this->items[$id]['quantity'] -= $quantity;
    }

    /**
     * Get the total price of all items in the cart.
     */
    public function getTotal(): float
    {
        $total = 0.0;
        foreach ($this->items as $item) {
            $total += $item['price'] * $item['quantity'];
        }
        return round($total, 2);
    }
}
