# PHP Email Validation Function

```php
<?php

/**
 * Validates an email address using a regular expression.
 *
 * @param string $email The email address to validate.
 * @return bool True if valid, false otherwise.
 */
function isValidEmail(string $email): bool
{
    // Trim whitespace and convert to lowercase (emails are case-insensitive)
    $email = trim($email);

    // Basic length check (max email length per RFC 5321 is 254 chars)
    if (strlen($email) === 0 || strlen($email) > 254) {
        return false;
    }

    $pattern = '/^[a-zA-Z0-9!#$%&\'*+\-\/=?^_`{|}~]'   // local part: first char (no dot)
        . '[a-zA-Z0-9!#$%&\'*+\-\/=?^_`{|}~.]*'         // local part: remaining chars
        . '(?<!\.)'                                      // local part must not end with a dot
        . '@'
        . '[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?' // domain labels
        . '(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*' // subdomains
        . '\.[a-zA-Z]{2,}$/';                           // TLD (min 2 letters)

    return preg_match($pattern, $email) === 1;
}
