```php
<?php

class ShoppingCart
{
    private array $items = [];

    /**
     * Add an item to the cart. If the item already exists, increase its quantity.
     *
     * @param string $name     Name of the item
     * @param float  $price    Price per unit
     * @param int    $quantity Quantity to add (default 1)
     */
    public function addItem(string $name, float $price, int $quantity = 1): void
    {
        if ($price < 0 || $quantity < 1) {
            throw new InvalidArgumentException('Price must be non-negative and quantity at least 1.');
        }

        if (isset($this->items[$name])) {
            $this->items[$name]['quantity'] += $quantity;
        } else {
            $this->items[$name] = [
                'name'     => $name,
                'price'    => $price,
                'quantity' => $quantity,
            ];
        }
    }

    /**
     * Remove an item from the cart. Optionally remove only part of the quantity.
     *
     * @param string $name     Name of the item
     * @param int|null $quantity Quantity to remove, or null to remove all
     * @throws InvalidArgumentException If item not found
     */
    public function removeItem(string $name, ?int $quantity = null): void
    {
        if (!isset($this->items[$name])) {
            throw new InvalidArgumentException("Item '$name' not found in cart.");
        }

        if ($quantity === null || $this->items[$name]['quantity'] <= $quantity) {
            unset($this->items[$name]);
        } else {
            $this->items[$name]['quantity'] -= $quantity;
        }
    }

    /**
     * Get the total price of all items in the cart.
     */
    public function getTotal(): float
    {
        $total = 0.0;
        foreach ($this->items as $item) {
            $total += $item['price'] * $item['quantity'];
        }
        return round($total, 2);
    }

    /**
     * Get all items in the cart.
     */
    public function getItems(): array
    {
        return $this->items;
    }
}
```

**Example usage:**

```php
$cart = new ShoppingCart();

$cart->addItem('Apple', 0.50, 4);
$cart->addItem('Bread', 2.25);
$cart->addItem('Milk', 1.75, 2);

$cart->removeItem('Bread');        // removes Bread entirely
$cart->removeItem('Apple', 1);     // removes 1 apple (3 remain)

echo $cart->getTotal();            // 5.75 (3 apples + 2 milk)
```

**Notes:**
- Items are keyed by name, so adding the same item again just increases its quantity.
- `removeItem()` can remove all of an item or just part of its quantity.
- The total is rounded to 2 decimal places to avoid floating-point artifacts. For production use with money, consider integers in cents or a library like `brick/money`.

