# PHP ShoppingCart Class

```php
<?php

class ShoppingCart
{
    private array $items = [];

    /**
     * Add an item to the cart.
     *
     * @param string $name     Item name
     * @param float  $price    Unit price
     * @param int    $quantity Quantity to add (default 1)
     * @return void
     */
    public function addItem(string $name, float $price, int $quantity = 1): void
    {
        if ($price < 0 || $quantity < 1) {
            throw new InvalidArgumentException('Price must be non-negative and quantity must be at least 1.');
        }

        $key = $this->findItemKey($name);

        if ($key !== null) {
            // Item already in cart — increase quantity
            $this->items[$key]['quantity'] += $quantity;
        } else {
            $this->items[] = [
                'name'     => $name,
                'price'    => $price,
                'quantity' => $quantity,
            ];
        }
    }

    /**
     * Remove an item from the cart (all quantities).
     *
     * @param string $name Item name
     * @return bool True if removed, false if not found
     */
    public function removeItem(string $name): bool
    {
        $key = $this->findItemKey($name);

        if ($key === null) {
            return false;
        }

        unset($this->items[$key]);
        $this->items = array_values($this->items); // re-index
        return true;
    }

    /**
     * Get the total price of all items in the cart.
     *
     * @return float
     */
    public function getTotal(): float
    {
        return array_sum(array_map(
            fn(array $item): float => $item['price'] * $item['quantity'],
            $this->items
        ));
    }

    /**
     * Get all items in the cart.
     *
     * @return array
     */
    public function getItems(): array
    {
        return $this->items;
    }

    /**
     * Find the array key of an item by name, or null if not found.
     */
    private function findItemKey(string $name): ?int
    {
        foreach ($this->items as $key => $item) {
            if ($item['name'] === $name) {
                return $key;
            }
        }
        return null;
    }
}
