```

- Regex validation confirms *syntax* only — it can't prove the mailbox actually exists. For real verification, send a confirmation email.

```php
<?php

/**
 * Validates an email address using a regular expression.
 *
 * @param string $email The email address to validate.
 * @return bool True if the email is valid, false otherwise.
 */
function isValidEmail(string $email): bool
{
    // Trim whitespace and check length constraints
    $email = trim($email);
    if ($email === '' || strlen($email) > 254) {
        return false;
    }

    // Local part: dot-atom, allowing quoted strings
    $local = '(?:[a-zA-Z0-9!#$%&\'*+/=?^_`{|}~-]+'
           . '(?:\.[a-zA-Z0-9!#$%&\'*+/=?^_`{|}~-]+)*'
           . '|"(?:[^"\\\\]|\\\\.)*")';

    // Domain: labels separated by dots, ending in an alphabetic TLD (2+ chars)
    $domain = '(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,}';

    $pattern = '/^' . $local . '@' . $domain . '$/';

    return (bool) preg_match($pattern, $email);
}
