```php
<?php

class ShoppingCart
{
    /** @var array<string, array{price: float, qty: int}> */
    private array $items = [];

    /**
     * Add an item to the cart.
     *
     * @param string $name  Product name (used as the unique key)
     * @param float  $price Unit price
     * @param int    $qty  Quantity to add
     */
    public function addItem(string $name, float $price, int $qty = 1): void
    {
        if ($name === '' || $price < 0 || $qty < 1) {
            throw new InvalidArgumentException('Invalid item data.');
        }

        if (isset($this->items[$name])) {
            // Already in the cart: increase the quantity.
            $this->items[$name]['qty'] += $qty;
        } else {
            $this->items[$name] = ['price' => $price, 'qty' => $qty];
        }
    }

    /**
     * Remove an item from the cart.
     *
     * @param string $name Product name
     * @param int|null $qty Quantity to remove; null removes the whole line
     */
    public function removeItem(string $name, ?int $qty = null): void
    {
        if (!isset($this->items[$name])) {
            return; // Nothing to remove
        }

        if ($qty === null || $qty >= $this->items[$name]['qty']) {
            unset($this->items[$name]);
            return;
        }

        $this->items[$name]['qty'] -= $qty;
    }

    /**
     * Get the total price of the cart.
     */
    public function getTotal(): float
    {
        $total = 0.0;

        foreach ($this->items as $item) {
            $total += $item['price'] * $item['qty'];
        }

        return round($total, 2);
    }

    /**
     * Number of distinct products in the cart.
     */
    public function count(): int
    {
        return count($this->items);
    }

    /**
     * Total number of units in the cart.
     */
    public function getQuantity(): int
    {
        return array_sum(array_column($this->items, 'qty'));
    }

    /**
     * All items in the cart.
     *
     * @return array<string, array{price: float, qty: int}>
     */
    public function getItems(): array
    {
        return $this->items;
    }

    /**
     * Empty the cart.
     */
    public function clear(): void
    {
        $this->items = [];
    }
}
```

### Usage

```php
<?php

require 'ShoppingCart.php';

$cart = new ShoppingCart();

$cart->addItem('Apple', 1.50, 3);
$cart->addItem('Bread', 2.25);
$cart->addItem('Apple', 1.50, 2);   // Adds to the existing line -> 5 apples

echo $cart->getTotal();   // 1.50*5 + 2.25 = 9.75
echo $cart->count();      // 2 distinct products
echo $cart->getQuantity();// 6 units

$cart->removeItem('Apple', 2);  // 3 apples left
echo $cart->getTotal();   // 1.50*3 + 2.25 = 6.75

$cart->removeItem('Bread');    // removes the whole line
echo $cart->getTotal();   // 4.50
