### Notes
- Items are keyed by name, so adding the same product twice increases its quantity instead of creating a duplicate line.
- `removeItem()` with no quantity removes the product entirely; with a quantity it removes just that many units.
- `getTotal()` rounds to 2 decimals to avoid floating-point artifacts (e.g. `0.1 + 0.2`).
- For real money handling, consider storing prices as integer cents and using `bcmath`/`intdiv` for arithmetic.

```php
<?php

declare(strict_types=1);

class ShoppingCart
{
    /** @var array<string, array{name: string, price: float, quantity: int}> */
    private array $items = [];

    /**
     * Add an item to the cart. If the item already exists, its quantity is increased.
     *
     * @throws InvalidArgumentException if the price is negative or the quantity is not positive.
     */
    public function addItem(string $name, float $price, int $quantity = 1): void
    {
        $name = trim($name);

        if ($name === '') {
            throw new InvalidArgumentException('Item name cannot be empty.');
        }
        if ($price < 0) {
            throw new InvalidArgumentException('Price cannot be negative.');
        }
        if ($quantity < 1) {
            throw new InvalidArgumentException('Quantity must be at least 1.');
        }

        if (isset($this->items[$name])) {
            $this->items[$name]['quantity'] += $quantity;
            return;
        }

        $this->items[$name] = [
            'name'     => $name,
            'price'    => $price,
            'quantity' => $quantity,
        ];
    }

    /**
     * Remove an item from the cart.
     *
     * @param int $quantity How many units to remove. Pass 0 (or use removeAllOf)
     *                      to remove the item entirely.
     *
     * @return bool True if something was removed.
     */
    public function removeItem(string $name, int $quantity = 1): bool
    {
        $name = trim($name);

        if (!isset($this->items[$name])) {
            return false;
        }

        if ($quantity <= 0) {
            unset($this->items[$name]);
            return true;
        }

        $this->items[$name]['quantity'] -= $quantity;

        if ($this->items[$name]['quantity'] <= 0) {
            unset($this->items[$name]);
        }

        return true;
    }

    /**
     * Total cost of all items in the cart.
     */
    public function getTotal(): float
    {
        $total = 0.0;

        foreach ($this->items as $item) {
            $total += $item['price'] * $item['quantity'];
        }

        return round($total, 2);
    }

    /**
     * Number of distinct items in the cart.
     */
    public function count(): int
    {
        return count($this->items);
    }

    /**
     * Total number of units in the cart.
     */
    public function getItemCount(): int
    {
        return array_sum(array_column($this->items, 'quantity'));
    }

    /**
     * @return array<string, array{name: string, price: float, quantity: int}>
     */
    public function getItems(): array
    {
        return $this->items;
    }

    public function isEmpty(): bool
    {
        return $this->items === [];
    }

    public function clear(): void
    {
        $this->items = [];
    }
}
