```php
<?php

declare(strict_types=1);

/**
 * A simple in-memory shopping cart.
 *
 * Items are stored keyed by their name, so adding the same product twice
 * increases its quantity rather than creating a duplicate entry.
 */
class ShoppingCart
{
    /**
     * @var array<string, array{name: string, price: float, quantity: int}>
     */
    private array $items = [];

    /**
     * Add a product to the cart.
     *
     * If the product is already in the cart, its quantity is increased.
     *
     * @throws InvalidArgumentException if the price is negative or the quantity is not positive.
     */
    public function addItem(string $name, float $price, int $quantity = 1): void
    {
        $name = trim($name);

        if ($name === '') {
            throw new InvalidArgumentException('Item name cannot be empty.');
        }
        if ($price < 0) {
            throw new InvalidArgumentException('Item price cannot be negative.');
        }
        if ($quantity < 1) {
            throw new InvalidArgumentException('Item quantity must be at least 1.');
        }

        if (isset($this->items[$name])) {
            $this->items[$name]['quantity'] += $quantity;
            return;
        }

        $this->items[$name] = [
            'name'     => $name,
            'price'    => $price,
            'quantity' => $quantity,
        ];
    }

    /**
     * Remove a product from the cart.
     *
     * @param int|null $quantity How many units to remove. Pass null (default) to
     *                           remove the product entirely.
     * @return bool True if something was removed, false if the item was not in the cart.
     */
    public function removeItem(string $name, ?int $quantity = null): bool
    {
        $name = trim($name);

        if (!isset($this->items[$name])) {
            return false;
        }

        if ($quantity === null) {
            unset($this->items[$name]);
            return true;
        }

        if ($quantity < 1) {
            throw new InvalidArgumentException('Item quantity must be at least 1.');
        }

        if ($quantity >= $this->items[$name]['quantity']) {
            unset($this->items[$name]);
        } else {
            $this->items[$name]['quantity'] -= $quantity;
        }

        return true;
    }

    /**
     * Total cost of everything in the cart, rounded to 2 decimal places.
     */
    public function getTotal(): float
    {
        $total = 0.0;

        foreach ($this->items as $item) {
            $total += $item['price'] * $item['quantity'];
        }

        return round($total, 2);
    }

    /**
     * Total number of individual units in the cart.
     */
    public function getItemCount(): int
    {
        $count = 0;

        foreach ($this->items as $item) {
            $count += $item['quantity'];
        }

        return $count;
    }

    /**
     * Whether the cart contains the given product.
     */
    public function hasItem(string $name): bool
    {
        return isset($this->items[trim($name)]);
    }

    /**
     * All items in the cart.
     *
     * @return array<string, array{name: string, price: float, quantity: int}>
     */
    public function getItems(): array
    {
        return $this->items;
    }

    /**
     * Empty the cart.
     */
    public function clear(): void
    {
        $this->items = [];
    }
}
