    {
        foreach ($items as $name => $item) {
            $this->addItem($name, $item['price'], $item['quantity'] ?? 1);
        }
    }

    /**
     * Add a product to the cart.
     * If the product is already present, its quantity is increased.
     *
     * @throws InvalidArgumentException
     */
    public function addItem(string $name, float $price, int $quantity = 1): void
    {
        $name = trim($name);

        if ($name === '') {
            throw new InvalidArgumentException('Item name cannot be empty.');
        }
        if ($price < 0) {
            throw new InvalidArgumentException("Price for '{$name}' cannot be negative.");
        }
        if ($quantity < 1) {
            throw new InvalidArgumentException("Quantity for '{$name}' must be at least 1.");
        }

        if (isset($this->items[$name])) {
            $this->items[$name]['quantity'] += $quantity;
        } else {
            $this->items[$name] = ['price' => $price, 'quantity' => $quantity];
        }
    }

    /**
     * Remove a product from the cart.
     * Removes $quantity units; if fewer are requested than present, the
     * remainder stays in the cart. If all units are removed, the entry
     * is deleted entirely.
     *
     * @return bool True if anything was removed.
     */
    public function removeItem(string $name, int $quantity = 1): bool
    {
        $name = trim($name);

        if (!isset($this->items[$name])) {
            return false;
        }
        if ($quantity < 1) {
            throw new InvalidArgumentException('Quantity to remove must be at least 1.');
        }

        $this->items[$name]['quantity'] -= $quantity;

        if ($this->items[$name]['quantity'] <= 0) {
            unset($this->items[$name]);
        }

        return true;
    }

    /**
     * Set the exact quantity of a product (0 removes it).
     */
    public function updateQuantity(string $name, int $quantity): void
    {
        if ($quantity < 0) {
            throw new InvalidArgumentException('Quantity cannot be negative.');
        }

        if ($quantity === 0) {
            unset($this->items[trim($name)]);
            return;
        }

        if (!isset($this->items[trim($name)])) {
            throw new InvalidArgumentException("Item '{$name}' is not in the cart.");
        }

        $this->items[trim($name)]['quantity'] = $quantity;
    }

    /**
     * Total cost of the cart (price x quantity for every item).
     */
    public function getTotal(): float
    {
        $total = 0.0;

        foreach ($this->items as $item) {
            $total += $item['price'] * $item['quantity'];
        }

        // Round to 2 decimal places to avoid floating-point drift (e.g. 0.1 + 0.2)
        return round($total, 2);
    }

    /**
     * Total number of individual units in the cart.
     */
    public function getItemCount(): int
    {
        return array_sum(array_column($this->items, 'quantity'));
    }

    /**
     * @return array<string, array{price: float, quantity: int}>
     */
    public function getItems(): array
    {
        return $this->items;
    }

    public function hasItem(string $name): bool
    {
        return isset($this->items[trim($name)]);
    }

    public function isEmpty(): bool
    {
        return $this->items === [];
    }

    public function clear(): void
    {
        $this->items = [];
    }
}
