require 'ShoppingCart.php';

$cart = new ShoppingCart();

$cart->addItem('Apple', 1.50);
$cart->addItem('Apple', 1.50, 2);      // merges -> 3 apples
$cart->addItem('Bread', 2.99, 2);

echo $cart->getTotal();                 // 10.48
echo PHP_EOL;
echo $cart->getQuantity('Apple');       // 3
echo PHP_EOL;

$cart->removeItem('Apple', 1);          // 2 apples left
echo $cart->getTotal();                 // 7.48

$cart->removeItem('Apple');             // removes the whole line
