    if (!mb_detect_encoding($string, 'UTF-8', true)) {
        $string = mb_convert_encoding($string, 'UTF-8', 'ISO-8859-1');
    }

    // Transliterate accented / non-Latin characters to ASCII
    if (function_exists('transliterator_transliterate')) {
        $string = transliterator_transliterate('Any-Latin; Latin-ASCII; Lower()', $string);
    } else {
        $string = iconv('UTF-8', 'ASCII//TRANSLIT//IGNORE', $string);
    }

    // Lowercase (multibyte-safe)
    $string = function_exists('mb_strtolower') ? mb_strtolower($string, 'UTF-8') : strtolower($string);

    // Replace any run of non-alphanumeric characters with a single hyphen
    $string = preg_replace('/[^a-z0-9]+/', '-', $string);

    // Strip leading/trailing hyphens
    return trim($string, '-');
}
