```php
<?php

/**
 * Turn a human-readable title into a URL-safe slug.
 *
 * @param string $string    The title to slugify.
 * @param string $separator Character(s) used to join the words.
 *
 * @return string The slug (empty string if nothing usable remains).
 */
function slugify($string, $separator = '-')
{
    $string = (string) $string;

    // Decode entities first, so "&amp;" doesn't turn into "&amp;-amp;".
    $string = html_entity_decode($string, ENT_QUOTES | ENT_HTML5, 'UTF-8');

    // Split accented letters into base letter + combining mark (é → e + ́).
    if (class_exists('Normalizer')) {
        $normalized = \Normalizer::normalize($string, \Normalizer::FORM_D);
        if ($normalized !== false) {
            $string = $normalized;
        }
    }

    // Transliterate to ASCII: é → e, ü → u, ß → ss, å → a, …
    if (function_exists('iconv')) {
        $ascii = @iconv('UTF-8', 'ASCII//TRANSLIT//IGNORE', $string);
        if ($ascii !== false) {
            $string = $ascii;
        }
    }

    // Some libc transliterations leave stray quotes behind ("é" → "'e").
    $string = str_replace(["'", '"', '`'], '', $string);

    // Drop any combining marks that survived (safety net).
    $string = preg_replace('/\p{Mn}/u', '', $string);

    // Lowercase, multibyte-aware when mbstring is available.
    $string = function_exists('mb_strtolower')
        ? mb_strtolower($string, 'UTF-8')
        : strtolower($string);

    // "&" reads better as the word "and".
    $string = preg_replace('/&+/', ' and ', $string);

    // Collapse every run of non-alphanumerics into a single separator.
    $string = preg_replace('/[^a-z0-9]+/', preg_quote($separator, '/'), $string);

    // Trim separators from both ends.
    $string = trim($string, $separator);

    return $string;
}
