    // 2. Fold accents and foreign scripts down to plain ASCII.
    $string = foldToAscii($string);

    // 3. Every run of non-alphanumeric characters becomes the separator.
    $string = preg_replace('/[^a-z0-9]+/u', $separator, $string) ?? '';

    // 4. Collapse repeated separators and trim them off both ends.
    $quoted = preg_quote($separator, '/');
    $string = preg_replace('/(?:' . $quoted . ')+/', $separator, $string) ?? '';
    $string = trim($string, $separator);

    // 5. Optionally shorten, without cutting a word in half.
    if ($maxLength > 0 && mb_strlen($string) > $maxLength) {
        $string = trim(mb_substr($string, 0, $maxLength), $separator);
        $cut = mb_strrpos($string, $separator);
        if ($cut !== false) {
            $string = trim(mb_substr($string, 0, $cut), $separator);
        }
    }

    return $string;
}

